_CORE_SRC = '# Action format: [(from_node, to_node, unit_type, count), ...]\n# Payout: equal capacities each serve min(capacity, demand / 2); otherwise\n# the larger capacity serves min(capacity, demand), and the smaller serves\n# min(capacity, demand - served_big). Moves happen before the payout.\n# Upkeep: 3.0 per heavy and 1.0 per light away from its own base, per turn.\n\nimport math\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 70\nTYPES = ("heavy", "light")\nCAPACITY = (8, 3)\nUPKEEP = (3.0, 1.0)\n\n\ndef served(capacity, opponent, demand):\n    """Exact revenue rule, from our point of view."""\n    if capacity == opponent:\n        return min(capacity, demand / 2.0)\n    if capacity > opponent:\n        return min(capacity, demand)\n    return min(capacity, demand - min(opponent, demand))\n\n\ndef margin(capacity, opponent, demand):\n    return (served(capacity, opponent, demand)\n            - served(opponent, capacity, demand))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for other in adjacency[node]:\n                if distance[other] < 0:\n                    distance[other] = distance[node] + 1\n                    queue.append(other)\n        distances.append(distance)\n    hops = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source != target and distances[source][target] > 0:\n                hops[source][target] = next(\n                    neighbor for neighbor in adjacency[source]\n                    if distances[neighbor][target]\n                    == distances[source][target] - 1\n                )\n    return adjacency, distances, hops\n\n\ndef legal_action(have, want, distances, hops, adjacency):\n    """Pair targets closest-first; validate against start-of-turn availability."""\n    combined = {}\n    n = len(adjacency)\n    for kind in range(2):\n        surplus = [max(0, have[kind][v] - want[kind][v]) for v in range(n)]\n        deficit = [max(0, want[kind][v] - have[kind][v]) for v in range(n)]\n        pairs = sorted(\n            (distances[s][t], s, t)\n            for s in range(n) if surplus[s]\n            for t in range(n) if deficit[t] and distances[s][t] > 0\n        )\n        for _, source, target in pairs:\n            count = min(surplus[source], deficit[target])\n            if count:\n                destination = hops[source][target]\n                key = (source, destination, kind)\n                combined[key] = combined.get(key, 0) + count\n                surplus[source] -= count\n                deficit[target] -= count\n\n    available = [row[:] for row in have]\n    result = []\n    for (source, destination, kind), count in sorted(combined.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = min(count, available[kind][source])\n        if count <= 0:\n            continue\n        available[kind][source] -= count\n        result.append((int(source), int(destination), TYPES[kind], int(count)))\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.base_demand = []\n        self.last_seen = []\n        self.last_counter = []\n        self.previous_target = None\n        self.bad_reports = 0\n\n    def _demand_model(self, obs, n, turn):\n        for v in range(n):\n            demand = obs["demand"][v]\n            if demand is not None:\n                counter = obs["surge_turns_left"][v] or 0\n                self.base_demand[v] = float(demand) / (3 if counter else 1)\n                self.last_seen[v] = turn\n                self.last_counter[v] = int(counter)\n\n    def _value_tables(self, obs, distances, deadline):\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        remaining = max(0, N_TURNS - turn)\n        # Discounting gives nearby earnings precedence without dropping the\n        # remaining game horizon. Surge probabilities are integrated exactly.\n        weights = [0.93 ** t for t in range(remaining)]\n        prefix = [0.0]\n        for weight in weights:\n            prefix.append(prefix[-1] + weight)\n        total_weight = prefix[-1]\n        diameter = max(max(row) for row in distances)\n        tables = []\n        for v in range(n):\n            base = self.base_demand[v]\n            known_left = max(\n                0, self.last_counter[v] - (turn - self.last_seen[v])\n            )\n            normal_weight = [0.0] * (remaining + 1)\n            surge_weight = [0.0] * (remaining + 1)\n            for t in range(remaining - 1, -1, -1):\n                if t < known_left:\n                    probability = 1.0\n                elif self.last_seen[v] == turn:\n                    probability = 1.0 - 0.9 ** min(t, 3)\n                else:\n                    probability = 0.271\n                normal_weight[t] = normal_weight[t + 1] + weights[t] * (1 - probability)\n                surge_weight[t] = surge_weight[t + 1] + weights[t] * probability\n            opponent = (8 * obs["opponent_heavy"][v]\n                        + 3 * obs["opponent_light"][v])\n            normal = []\n            surge = []\n            baseline_normal = margin(0, opponent, base)\n            baseline_surge = margin(0, opponent, 3 * base)\n            for capacity in range(141):\n                normal.append(margin(capacity, opponent, base) - baseline_normal)\n                surge.append(margin(capacity, opponent, 3 * base) - baseline_surge)\n            by_distance = []\n            for distance in range(diameter + 1):\n                arrival = min(remaining, max(0, distance - 1))\n                nw, sw = normal_weight[arrival], surge_weight[arrival]\n                by_distance.append([\n                    nw * normal[c] + sw * surge[c] for c in range(141)\n                ])\n            tables.append(by_distance)\n        return tables, prefix, total_weight\n\n    def _plan(self, obs, have, distances, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        tables, prefix, weight = self._value_tables(obs, distances, deadline)\n        available = [row[:] for row in have]\n        wanted = [[0] * n for _ in range(2)]\n        allocated_capacity = [0] * n\n        opponent_capacity = [\n            8 * obs["opponent_heavy"][v] + 3 * obs["opponent_light"][v]\n            for v in range(n)\n        ]\n        sources = [(kind, source) for kind in range(2)\n                   for source in range(n) if available[kind][source]]\n        # Priority payout is NOT concave at the opponent\'s capacity threshold.\n        # Include bundles that tie or exceed it, rather than assuming concavity.\n        while time.perf_counter() < deadline:\n            best = None\n            best_score = 0.0\n            for kind, source in sources:\n                count = available[kind][source]\n                if not count:\n                    continue\n                cap = CAPACITY[kind]\n                cost = UPKEEP[kind]\n                home_distance = distances[source][home]\n                home_arrival = min(len(prefix) - 1, max(0, home_distance - 1))\n                return_cost = cost * prefix[home_arrival]\n                for target in range(n):\n                    if target == home or target == obs["opponent_base"]:\n                        continue\n                    distance = distances[source][target]\n                    if distance < 0:\n                        continue\n                    current = allocated_capacity[target]\n                    threshold = opponent_capacity[target] - current\n                    bundle = max(1, threshold // cap + 1)\n                    candidates = (1, bundle)\n                    for amount in candidates:\n                        if amount > count:\n                            continue\n                        after = current + cap * amount\n                        if after > 140:\n                            continue\n                        table = tables[target][distance]\n                        gain = (table[after] - table[current]\n                                - amount * (cost * weight - return_cost))\n                        # Prefer established commitments, but only slightly.\n                        if self.previous_target is not None:\n                            committed = self.previous_target[kind][target]\n                            if wanted[kind][target] < committed:\n                                gain += min(amount, committed - wanted[kind][target]) * 0.16 * weight\n                        if source == target:\n                            gain += 0.10 * weight * amount\n                        score = gain / amount\n                        if score > best_score + 1e-9:\n                            best_score = score\n                            best = (kind, source, target, amount)\n            if best is None:\n                break\n            kind, source, target, amount = best\n            available[kind][source] -= amount\n            wanted[kind][target] += amount\n            allocated_capacity[target] += CAPACITY[kind] * amount\n        for kind in range(2):\n            wanted[kind][home] += sum(available[kind])\n        return wanted\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs["edges"])\n            self.base_demand = [3.8] * n\n            self.last_seen = [-100] * n\n            self.last_counter = [0] * n\n        adjacency, distances, hops = self.map_data\n        home = int(obs["player_base"])\n        enemy_home = int(obs["opponent_base"])\n        self._demand_model(obs, n, int(obs["turn"]))\n        self.base_demand[home] = 0.0\n        self.base_demand[enemy_home] = 0.0\n        have = [list(obs["player_heavy"]), list(obs["player_light"])]\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            # Conservative fallback: no new deployments, return along legal paths.\n            wanted = [[0] * n for _ in range(2)]\n            for kind in range(2):\n                wanted[kind][home] = sum(have[kind])\n        else:\n            wanted = self._plan(obs, have, distances, deadline)\n        action = legal_action(have, wanted, distances, hops, adjacency)\n        self.previous_target = [row[:] for row in wanted]\n        return action\n'
_CORE_CLASS = 'Strategy'
